import { ProviderError } from './errors';

/**
 * The Anthropic and OpenAI SDKs share an error shape (both are generated by
 * Stainless): an `APIError` with an HTTP `status`, plus `APIConnectionError`
 * and `APIUserAbortError` subclasses. This maps that shape to our ErrorCodes.
 */
export interface SdkErrorInfo {
  status: number | undefined;
  /** Provider error type, e.g. Anthropic's `overloaded_error` (set for errors that arrive mid-stream, which have no status). */
  type?: string | null;
  isConnectionError: boolean;
  /** The provider's own message. Only surfaced for bad requests, where it's useful (e.g. "prompt is too long"). */
  message: string;
}

export function toProviderError(label: string, info: SdkErrorInfo, cause: unknown): ProviderError {
  const { status, type, isConnectionError, message } = info;
  const opts = { cause };

  if (isConnectionError) {
    return new ProviderError('network', `Could not reach ${label}. Please try again.`, opts);
  }
  if (
    status === 401 ||
    status === 403 ||
    type === 'authentication_error' ||
    type === 'permission_error'
  ) {
    return new ProviderError(
      'auth',
      `${label} rejected the server's API key. Check the key in apps/server/.env.`,
      opts,
    );
  }
  if (status === 429 || type === 'rate_limit_error') {
    return new ProviderError(
      'rate_limited',
      `${label} is rate limiting requests. Wait a moment and retry.`,
      opts,
    );
  }
  if (status === 529 || type === 'overloaded_error') {
    return new ProviderError(
      'overloaded',
      `${label} is overloaded right now. Please retry shortly.`,
      opts,
    );
  }
  if (status !== undefined && status >= 400 && status < 500) {
    return new ProviderError(
      'bad_request',
      `${label} could not process the request: ${message}`,
      opts,
    );
  }
  return new ProviderError('upstream', `${label} returned an error. Please retry.`, opts);
}
